#!/usr/bin/env bash
# muster/lib/commands/logs_api.sh — `muster logs <svc> --tail N [--follow] [--json]`
#
# --tail uses the stack's own log command so it can stop after N lines
# (log hooks generated by setup always follow):
#   k8s      kubectl logs deployment/<name> --all-containers --tail=N [-f]
#   compose  docker compose -f <file> logs --no-color --tail N [-f] <service>
#   docker   docker logs --tail N [-f] <container>
#   dev      tail -n N [-f] .muster/logs/<svc>.log
#   other    the logs hook (MUSTER_LOGS_TAIL / MUSTER_LOGS_FOLLOW set; output
#            capped after 5s without --follow), else the latest deploy log
# --json without --tail follows the usual source (logs hook / just recipe /
# latest deploy log) and wraps each line as an event.

source "$MUSTER_ROOT/lib/core/engine.sh"
source "$MUSTER_ROOT/lib/core/remote.sh"

# Usage: _logs_api target tail_n follow(true|false) json(true|false)
_logs_api() {
  local target="$1" tail_n="$2" follow="$3" json="$4"

  if [[ "$json" == "true" ]]; then
    source "$MUSTER_ROOT/lib/core/auth.sh"
    _json_auth_gate "read" || return 1
  fi

  _logs_api_err() {
    if [[ "$json" == "true" ]]; then
      _json_error "$1" "$2"
    else
      err "$2" >&2
    fi
  }

  if [[ -z "$target" ]]; then
    _logs_api_err "usage" "No service given. Usage: muster logs <service> --tail N"
    return 1
  fi
  local _known
  _known=" $(config_services | tr '\n' ' ') "
  if [[ "$_known" != *" ${target} "* ]]; then
    _logs_api_err "unknown_service" "Unknown service: ${target}"
    return 1
  fi

  local project_dir
  project_dir="$(dirname "$CONFIG_FILE")"
  local hook_dir="${project_dir}/.muster/hooks/${target}"
  local hook="${hook_dir}/logs.sh"
  local stack
  stack=$(_engine_service_stack "$target" "$project_dir")
  local fflag="" source="" script=""
  local run=()

  local latest_log
  latest_log=$(ls -t "${project_dir}/.muster/logs/${target}-"*.log 2>/dev/null | head -1)

  if [[ -n "$tail_n" ]]; then
    case "$stack" in
      k8s|compose|docker)
        script=$(mktemp "${TMPDIR:-/tmp}/muster-logs.XXXXXX") || return 1
        case "$stack" in
          k8s)
            [[ "$follow" == "true" ]] && fflag=" -f"
            printf 'kubectl logs %q -n %q --all-containers --tail=%d%s\n' \
              "deployment/$(_engine_k8s_deployment "$target")" "$(_engine_k8s_namespace "$target")" "$tail_n" "$fflag" > "$script"
            source="kubectl"
            ;;
          compose)
            [[ "$follow" == "true" ]] && fflag=" -f"
            printf 'docker compose -f %q logs --no-color --tail %d%s %q\n' \
              "$(_engine_compose_file "$target" "$project_dir")" "$tail_n" "$fflag" "$(_engine_container_name "$target" "$project_dir")" > "$script"
            source="docker compose"
            ;;
          docker)
            [[ "$follow" == "true" ]] && fflag=" -f"
            printf 'docker logs --tail %d%s %q\n' "$tail_n" "$fflag" "$(_engine_container_name "$target" "$project_dir")" > "$script"
            source="docker"
            ;;
        esac
        run=(_engine_run_script "$target" "$script" "$(k8s_env_for_service "$target")")
        ;;
      *)
        local dev_log="${project_dir}/.muster/logs/${target}.log"
        if [[ "$stack" == "dev" && -f "$dev_log" ]]; then
          source="file"
          if [[ "$follow" == "true" ]]; then run=(tail -n "$tail_n" -f "$dev_log"); else run=(tail -n "$tail_n" "$dev_log"); fi
        elif [[ -x "$hook" ]]; then
          source="hook"
          export MUSTER_LOGS_TAIL="$tail_n"
          if [[ "$follow" == "true" ]]; then
            export MUSTER_LOGS_FOLLOW=1
            run=("$hook")
          else
            export MUSTER_LOGS_FOLLOW=0
            # Follow-style hooks never exit: cap them, then keep the last N lines
            run=(_logs_api_capped "$hook" "$tail_n" "$project_dir")
          fi
        elif [[ -n "$latest_log" ]]; then
          source="deploy_log"
          if [[ "$follow" == "true" ]]; then run=(tail -n "$tail_n" -f "$latest_log"); else run=(tail -n "$tail_n" "$latest_log"); fi
        fi
        ;;
    esac
  else
    # --json, follow the usual source
    if _just_available "$hook_dir" && _just_has_recipe "$hook_dir" "logs"; then
      source="hook"
      run=(just --justfile "${hook_dir}/justfile" logs)
    elif [[ -x "$hook" ]]; then
      source="hook"
      run=("$hook")
    elif [[ -n "$latest_log" ]]; then
      source="deploy_log"
      run=(tail -f "$latest_log")
    fi
  fi

  if (( ${#run[@]} == 0 )); then
    [[ -n "$script" ]] && rm -f "$script"
    _logs_api_err "no_logs" "No log hook and no deploy logs found for ${target}"
    return 1
  fi

  local rc=0 _l
  if [[ "$json" == "true" ]]; then
    local svc_json src_json
    svc_json=$(_json_str "$target")
    src_json=$(_json_str "$source")
    "${run[@]}" 2>&1 | while IFS= read -r _l || [[ -n "$_l" ]]; do
      printf '{"event":"log","service":%s,"source":%s,"line":"%s"}\n' "$svc_json" "$src_json" "$(_json_esc "${_l//$_JSON_CR/}")"
    done
    rc=${PIPESTATUS[0]}
    printf '{"event":"end","service":%s,"source":%s,"exit_code":%d}\n' "$svc_json" "$src_json" "$rc"
  else
    "${run[@]}" 2>&1
    rc=$?
  fi
  [[ -n "$script" ]] && rm -f "$script"
  unset MUSTER_LOGS_TAIL MUSTER_LOGS_FOLLOW
  return $rc
}

# Run a (follow-style) log hook for up to 5s, then stop it and everything it
# started, and print its last N lines.
# Usage: _logs_api_capped hook tail_n project_dir
_logs_api_capped() {
  local hook="$1" n="$2" dir="$3" out p i=0
  out=$(mktemp "${TMPDIR:-/tmp}/muster-logs-out.XXXXXX") || return 1
  (cd "$dir" && exec "$hook") > "$out" 2>&1 &
  p=$!
  while (( i < 50 )) && kill -0 "$p" 2>/dev/null; do
    sleep 0.1
    i=$(( i + 1 ))
  done
  kill -0 "$p" 2>/dev/null && _kill_tree_hard "$p"
  wait "$p" 2>/dev/null
  tail -n "$n" "$out"
  rm -f "$out"
  return 0
}
